"""Stage bounded open-file STFS support against the pinned SDK.

Not a guest kernel ABI implementation: callers must supply a real open IFile.
The read-only snapshot does not authenticate or modify user profile state.
"""
import argparse
import json
from pathlib import Path

REPLACEMENTS = json.loads("{\"src/filesystem/container.h\":[[\"namespace rex::filesystem {\\n\",\"namespace rex::filesystem {\\n\\nclass IFile;\\n\"],[\"  [[nodiscard]] static Result<Container> Open(const std::filesystem::path& path);\",\"  [[nodiscard]] static Result<Container> Open(const std::filesystem::path& path);\\n\\n  // Read-only bounded STFS snapshot of an already opened guest file.\\n  [[nodiscard]] static Result<Container> OpenSTFS(IFile& source);\"],[\"  Container();\",\"  Container();\\n  [[nodiscard]] std::span<const u8> FileBytes(size_t index) const;\"],[\"  std::vector<std::unique_ptr<memory::MappedMemory>> files_;\",\"  std::vector<std::unique_ptr<memory::MappedMemory>> files_;\\n  std::vector<u8> snapshot_;\"]],\"src/filesystem/container.cpp\":[[\"#include <rex/filesystem/file_system_error.h>\",\"#include <rex/filesystem/file_system_error.h>\\n#include <rex/filesystem/file.h>\"],[\"const ContainerNode* Container::Find(std::string_view path) const {\",\"Result<Container> Container::OpenSTFS(IFile& source) {\\n  constexpr u64 kMaximumSnapshotBytes = 64ull * 1024 * 1024;\\n  constexpr size_t kReadChunk = 64 * 1024;\\n  const auto info = source.GetInfo();\\n  if (HasFlags(info.attributes, FileAttributes::kDirectory)) {\\n    return Err<Container>(BuildError(FileSystemError::kIsDirectory, \\\"STFS source is a directory\\\"));\\n  }\\n  if (!HasFlags(source.GetAccess(), Access::kReadData)) {\\n    return Err<Container>(BuildError(FileSystemError::kAccessDenied, \\\"STFS source is not readable\\\"));\\n  }\\n  if (info.size < sizeof(XContentPackageHeader)) {\\n    return Err<Container>(BuildError(FileSystemError::kCorrupt, \\\"STFS source header is truncated\\\"));\\n  }\\n  if (info.size > kMaximumSnapshotBytes) {\\n    return Err<Container>(BuildError(FileSystemError::kUnsupported, \\\"STFS source exceeds snapshot limit\\\"));\\n  }\\n  Container container;\\n  container.snapshot_.resize(static_cast<size_t>(info.size));\\n  for (size_t offset = 0; offset < container.snapshot_.size();) {\\n    auto chunk = std::span(container.snapshot_).subspan(\\n        offset, std::min(kReadChunk, container.snapshot_.size() - offset));\\n    auto read = source.Read(chunk, offset);\\n    if (!read) {\\n      return Err<Container>(read.error());\\n    }\\n    if (*read != chunk.size()) {\\n      return Err<Container>(BuildError(FileSystemError::kCorrupt, \\\"STFS source returned a short read\\\"));\\n    }\\n    offset += *read;\\n  }\\n  source.Refresh();\\n  if (source.GetInfo().size != info.size) {\\n    return Err<Container>(BuildError(FileSystemError::kCorrupt, \\\"STFS source changed size while reading\\\"));\\n  }\\n  REX_TRY(XContentPackageHeader header, ReadSTFSHeader(container.snapshot_));\\n  if (memory::load<BE<XContentVolumeType>>(&header.metadata.volume_type) != XContentVolumeType::kSTFS) {\\n    return Err<Container>(BuildError(FileSystemError::kUnsupported, \\\"open-file mount supports STFS only\\\"));\\n  }\\n  container.header_ = std::make_unique<XContentPackageHeader>(header);\\n  container.total_size_ = container.snapshot_.size();\\n  container.nodes_.emplace_back().info.attributes = FileAttributes::kDirectory;\\n  REX_TRY_VOID(detail::ParseSTFS(*container.header_, container.snapshot_, container.nodes_));\\n  return container;\\n}\\n\\nstd::span<const u8> Container::FileBytes(size_t index) const {\\n  if (!snapshot_.empty()) {\\n    return index == 0 ? std::span<const u8>(snapshot_) : std::span<const u8>{};\\n  }\\n  return index < files_.size() ? BytesOf(*files_[index]) : std::span<const u8>{};\\n}\\n\\nconst ContainerNode* Container::Find(std::string_view path) const {\"],[\"const std::span<const u8> file = BytesOf(*files_[extent.file]);\",\"const std::span<const u8> file = FileBytes(extent.file);\",2]],\"src/filesystem/container_provider.h\":[[\"  [[nodiscard]] static Result<std::unique_ptr<Provider>> Create(const MountEntry& entry);\",\"  [[nodiscard]] static Result<std::unique_ptr<Provider>> Create(const MountEntry& entry);\\n  [[nodiscard]] static Result<std::unique_ptr<Provider>> CreateSTFS(const MountEntry& entry, IFile& source);\"],[\" private:\\n  void Build\",\" private:\\n  [[nodiscard]] static Result<std::unique_ptr<Provider>> CreateParsed(const MountEntry& entry, Container container);\\n  void Build\"]],\"src/filesystem/container_provider.cpp\":[[\"  REX_TRY(Container container, Container::Open(entry.source));\\n  if (!TypeMatches\",\"  REX_TRY(Container container, Container::Open(entry.source));\\n  return CreateParsed(entry, std::move(container));\\n}\\n\\nResult<std::unique_ptr<Provider>> ContainerProvider::CreateSTFS(const MountEntry& entry, IFile& source) {\\n  REX_TRY(Container container, Container::OpenSTFS(source));\\n  return CreateParsed(entry, std::move(container));\\n}\\n\\nResult<std::unique_ptr<Provider>> ContainerProvider::CreateParsed(const MountEntry& entry, Container container) {\\n  if (!TypeMatches\"]],\"include/rex/filesystem/file_system.h\":[[\"  [[nodiscard]] virtual Result<void> Mount(const MountEntry& entry) = 0;\",\"  [[nodiscard]] virtual Result<void> Mount(const MountEntry& entry) = 0;\\n\\n  /** Mount a read-only STFS snapshot from an existing guest file, never a host path. */\\n  [[nodiscard]] virtual Result<void> MountStfsFile(std::string_view path, IFile& source) = 0;\"]],\"src/filesystem/file_system.h\":[[\"  [[nodiscard]] Result<void> Mount(const MountEntry& entry) override;\",\"  [[nodiscard]] Result<void> Mount(const MountEntry& entry) override;\\n  [[nodiscard]] Result<void> MountStfsFile(std::string_view path, IFile& source) override;\"]],\"src/filesystem/file_system.cpp\":[[\"#include \\\"filesystem/node_file.h\\\"\",\"#include \\\"filesystem/node_file.h\\\"\\n#include \\\"filesystem/container_provider.h\\\"\"],[\"Result<void> FileSystem::Unmount(std::string_view path) {\",\"Result<void> FileSystem::MountStfsFile(std::string_view path, IFile& source) {\\n  // The caller chooses one canonical device name. Refuse aliases, nested\\n  // mount points, malformed paths and any shadowing of the active namespace.\\n  constexpr std::string_view prefix = \\\"\\\\\\\\Device\\\\\\\\\\\";\\n  if (!string::utf8_starts_with_case(path, prefix) || path.size() <= prefix.size() ||\\n      path.size() > 128 ||\\n      path.substr(prefix.size()).find_first_not_of(\\n          \\\"abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-\\\") != std::string_view::npos) {\\n    return Err(BuildError(FileSystemError::kInvalidPath, \\\"invalid STFS device name\\\"));\\n  }\\n  const std::string name(path);\\n  std::lock_guard lock(mutex_);\\n  auto intersects = [&](std::string_view other) {\\n    return StartsWithComponents(name, other) || StartsWithComponents(other, name);\\n  };\\n  if (std::ranges::any_of(providers_, [&](const auto& p) { return intersects(p->GetMountPath()); }) ||\\n      std::ranges::any_of(links_, [&](const auto& link) { return intersects(link.first); })) {\\n    return Err(BuildError(FileSystemError::kMountExists, \\\"STFS device name already occupied\\\"));\\n  }\\n  REX_TRY(std::unique_ptr<Provider> provider, ContainerProvider::CreateSTFS(\\n      {name, ProviderType::kSTFS, {}, MountFlags::kNone, {}}, source));\\n  providers_.push_back(std::move(provider));\\n  REXFS_DEBUG(\\\"mounted STFS open-file snapshot at '{}'\\\", name);\\n  return Ok();\\n}\\n\\nResult<void> FileSystem::Unmount(std::string_view path) {\"]]}")

def apply(root: Path, tests: Path) -> None:
    updates = {}
    for name, replacements in REPLACEMENTS.items():
        p = root / name
        source = p.read_text(encoding="utf-8")
        for old, new, *counts in replacements:
            count = counts[0] if counts else 1
            if source.count(old) != count:
                raise ValueError(f"{name}: expected {count} exact anchors")
            source = source.replace(old, new)
        updates[p] = source
    p = root / "tests/unit/filesystem/file_system_test.cpp"
    source = p.read_text(encoding="utf-8")
    marker = "[metro_stfs_open_file]"
    if marker in source:
        raise ValueError("tests already staged")
    updates[p] = source + "\n" + tests.read_text(encoding="utf-8")
    for p, source in updates.items():
        p.write_text(source, encoding="utf-8")
    print(f"Staged {len(updates)} STFS open-file source/test updates")

if __name__ == "__main__":
    p = argparse.ArgumentParser()
    p.add_argument("sdk", type=Path)
    p.add_argument("--tests", type=Path, required=True)
    a = p.parse_args()
    apply(a.sdk, a.tests)
